class GameScreen extends StatefulWidget {
  const GameScreen({super.key});

  @override
  State<GameScreen> createState() => _GameScreenState();
}

class _GameScreenState extends State<GameScreen> {
  final math.Random _random = math.Random();
  SharedPreferences? _prefs;
  int _level = 0;
  int _unlocked = 0;
  int _coins = 120;
  String _lastGiftDay = '';
  List<String> _wheelLetters = [];
  final Set<String> _solved = {};
  final Set<String> _bonuses = {};
  final Set<String> _hintCells = {};
  final Set<int> _completedLevels = {};
  final List<int> _dragged = [];
  String _notice = 'Harfleri parmağınla birleştir';

  PuzzleLevel get _puzzle => _levels[_level];
  bool get _complete => _puzzle.answers.every((w) => _solved.contains(w.word));
  String get _selection => _dragged.map((i) => _wheelLetters[i]).join();

  @override
  void initState() {
    super.initState();
    _wheelLetters = _levels.first.letters.split('');
    _restore();
  }

  Future<void> _restore() async {
    final prefs = await SharedPreferences.getInstance();
    if (!mounted) return;
    _prefs = prefs;
    _unlocked = (prefs.getInt('unlocked') ?? 0).clamp(0, _levels.length - 1).toInt();
    _level = (prefs.getInt('current_level') ?? 0).clamp(0, _unlocked).toInt();
    _coins = prefs.getInt('coins') ?? 120;
    _lastGiftDay = prefs.getString('gift_date') ?? '';
    _completedLevels.addAll(
      (prefs.getStringList('finished_levels') ?? []).map(int.tryParse).whereType<int>(),
    );
    _openLevel(_level);
  }

  void _openLevel(int index) {
    if (index > _unlocked || index < 0 || index >= _levels.length) return;
    setState(() {
      _level = index;
      _wheelLetters = _levels[index].letters.split('');
      _solved
        ..clear()
        ..addAll(_prefs?.getStringList('solved_$index') ?? []);
      _bonuses
        ..clear()
        ..addAll(_prefs?.getStringList('bonuses_$index') ?? []);
      _hintCells
        ..clear()
        ..addAll(_prefs?.getStringList('hints_$index') ?? []);
      _dragged.clear();
      _notice = 'Harfleri parmağınla birleştir';
    });
    _prefs?.setInt('current_level', index);
  }

  void _saveProgress() {
    _prefs?.setStringList('solved_$_level', _solved.toList());
    _prefs?.setStringList('bonuses_$_level', _bonuses.toList());
    _prefs?.setStringList('hints_$_level', _hintCells.toList());
    _prefs?.setStringList('finished_levels', _completedLevels.map((e) => '$e').toList());
    _prefs?.setInt('coins', _coins);
    _prefs?.setInt('unlocked', _unlocked);
  }

  void _handleDrag(Offset local, double size) {
    final index = LetterWheelPainter.hitLetter(local, size, _wheelLetters.length);
    if (index == null) return;
    if (_dragged.isNotEmpty && _dragged.last == index) return;
    setState(() {
      if (_dragged.length > 1 && _dragged[_dragged.length - 2] == index) {
        _dragged.removeLast();
      } else if (!_dragged.contains(index)) {
        _dragged.add(index);
      }
    });
  }

  void _submitWord() {
    if (_dragged.isEmpty) return;
    final word = _selection;
    final targets = _puzzle.answers.map((e) => e.word).toSet();
    setState(() {
      _dragged.clear();
      if (targets.contains(word)) {
        if (_solved.add(word)) {
          _coins += 10;
          _notice = '$word bulundu!  +10 altın';
          if (_complete && _completedLevels.add(_level)) {
            _coins += 40;
            _notice = 'Bölüm tamamlandı!  +40 altın';
            if (_level + 1 < _levels.length) {
              _unlocked = math.max(_unlocked, _level + 1);
            }
          }
        } else {
          _notice = '$word zaten bulundu';
        }
      } else if (_puzzle.bonusWords.contains(word)) {
        if (_bonuses.add(word)) {
          _coins += 5;
          _notice = 'Bonus kelime: $word  +5 altın';
        } else {
          _notice = 'Bu bonus kelimeyi bulmuştun';
        }
      } else {
        _notice = '$word bu bölümün kelime listesinde yok';
      }
    });
    _saveProgress();
  }

  void _shuffle() {
    setState(() {
      final previous = _wheelLetters.join();
      for (int i = 0; i < 6; i++) {
        _wheelLetters.shuffle(_random);
        if (_wheelLetters.join() != previous) break;
      }
      _dragged.clear();
      _notice = 'Harfler karıştırıldı';
    });
  }

  void _hint() {
    if (_complete) return;
    if (_coins < 25) {
      setState(() => _notice = 'İpucu için 25 altın gerekiyor');
      return;
    }
    final cells = _puzzle.cells;
    for (final word in _puzzle.answers.where((w) => !_solved.contains(w.word))) {
      for (int i = 0; i < word.word.length; i++) {
        final row = word.row + (word.down ? i : 0);
        final col = word.col + (word.down ? 0 : i);
        final id = '$row:$col';
        if (!_hintCells.contains(id) && !_isSolvedCell(row, col)) {
          setState(() {
            _hintCells.add(id);
            _coins -= 25;
            _notice = 'İpucu açıldı: ${cells[id]}  −25 altın';
          });
          _saveProgress();
          return;
        }
      }
    }
    setState(() => _notice = 'Açılabilecek başka harf kalmadı');
  }

  bool _isSolvedCell(int row, int col) {
    for (final answer in _puzzle.answers) {
      if (!_solved.contains(answer.word)) continue;
      for (int i = 0; i < answer.word.length; i++) {
        if (answer.row + (answer.down ? i : 0) == row &&
            answer.col + (answer.down ? 0 : i) == col) return true;
      }
    }
    return false;
  }

  void _next() {
    if (!_complete) return;
    if (_level + 1 >= _levels.length) {
      _showFinished();
    } else {
      _openLevel(_level + 1);
    }
  }

  void _showFinished() {
    showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Tebrikler! 🏆'),
        content: const Text(
          'Altı şehrin bütün bulmacalarını tamamladın. '
          'Yeni şehirler ve daha geniş Türkçe sözlük sonraki sürümde eklenecek.',
        ),
        actions: [TextButton(onPressed: () => Navigator.pop(dialogContext),
          child: const Text('Harika!'))],
      ),
    );
  }

  void _showMap() {
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: const Color(0xFFFFF7EA),
      showDragHandle: true,
      isScrollControlled: true,
      builder: (sheetContext) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(20, 8, 20, 24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Şehir haritası',
                style: TextStyle(fontSize: 24, fontWeight: FontWeight.w800)),
              const SizedBox(height: 14),
              ...List.generate(_levels.length, (i) {
                final locked = i > _unlocked;
                return ListTile(
                  leading: CircleAvatar(
                    backgroundColor: i == _level
                      ? const Color(0xFFBD8B55) : const Color(0xFFF1E1CA),
                    child: Text('${i + 1}', style: TextStyle(
                      color: i == _level ? Colors.white : const Color(0xFF614B38))),
                  ),
                  title: Text(_levels[i].city, style: const TextStyle(fontWeight: FontWeight.w700)),
                  subtitle: Text(_completedLevels.contains(i) ? 'Tamamlandı ✓'
                    : locked ? 'Kilitli' : _levels[i].subtitle),
                  trailing: Icon(locked ? Icons.lock_outline : Icons.chevron_right),
                  onTap: locked ? null : () {
                    Navigator.pop(sheetContext);
                    _openLevel(i);
                  },
                );
              }),
            ],
          ),
        ),
      ),
    );
  }

  void _showRewards() {
    final today = DateTime.now().toIso8601String().substring(0, 10);
    final claimed = _lastGiftDay == today;
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: const Color(0xFFFFF7EA),
      showDragHandle: true,
      builder: (sheetContext) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            const Icon(Icons.card_giftcard, size: 52, color: Color(0xFFBD8B55)),
            const SizedBox(height: 8),
            const Text('Günlük ödül', style: TextStyle(fontSize: 26, fontWeight: FontWeight.w800)),
            const SizedBox(height: 10),
            const Text('Her gün 35 altın kazan. Bulduğun bonus kelimeler de altın kazandırır.',
              textAlign: TextAlign.center),
            const SizedBox(height: 22),
            FilledButton.icon(
              onPressed: claimed ? null : () {
                setState(() {
                  _coins += 35;
                  _lastGiftDay = today;
                  _notice = 'Günlük ödül alındı!  +35 altın';
                });
                _prefs?.setString('gift_date', today);
                _saveProgress();
                Navigator.pop(sheetContext);
              },
              icon: const Icon(Icons.stars_rounded),
              label: Text(claimed ? 'Bugünkü ödülü aldın' : '35 altını al'),
            ),
          ]),
        ),
      ),
    );
  }

  // Premium arayüz — oyun mekaniği ve kayıt sistemi aynı kalır.
  static const _navy = Color(0xFF0C2440);
  static const _gold = Color(0xFFFFD36E);
  static const _cream = Color(0xFFFFF7E6);

  @override
  Widget build(BuildContext context) {
    final firstCity = _level == 0;
    return Scaffold(
      backgroundColor: _navy,
      body: Stack(
        children: [
          Positioned.fill(
            child: firstCity
                ? Image.memory(_istanbulBackground, fit: BoxFit.cover,
                    alignment: Alignment.center)
                : const CustomPaint(painter: ScenicCityPainter()),
          ),
          Positioned.fill(
            child: DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  stops: const [0, .17, .46, .69, 1],
                  colors: [
                    _navy.withOpacity(.76),
                    _navy.withOpacity(.14),
                    _navy.withOpacity(.20),
                    _navy.withOpacity(.18),
                    _navy.withOpacity(.60),
                  ],
                ),
              ),
            ),
          ),
          SafeArea(
            child: LayoutBuilder(builder: (context, viewport) {
              final narrow = viewport.maxWidth < 370;
              final compact = viewport.maxHeight < 730;
              final wheelSize = math.min(
                viewport.maxWidth - (narrow ? 108 : 132),
                compact ? 235.0 : 286.0,
              ).clamp(206.0, 286.0).toDouble();
              final boardMax = compact ? 38.0 : 47.0;
              return SingleChildScrollView(
                physics: const BouncingScrollPhysics(),
                child: ConstrainedBox(
                  constraints: BoxConstraints(minHeight: viewport.maxHeight),
                  child: Padding(
                    padding: EdgeInsets.fromLTRB(narrow ? 10 : 15, 10,
                        narrow ? 10 : 15, 15),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        _premiumTopBar(narrow),
                        SizedBox(height: compact ? 13 : 21),
                        _cityPlaque(),
                        SizedBox(height: compact ? 18 : 25),
                        _premiumBoard(boardMax),
                        SizedBox(height: compact ? 13 : 21),
                        _selectionMessage(),
                        SizedBox(height: compact ? 9 : 13),
                        _wheelAndActions(wheelSize, narrow),
                        SizedBox(height: compact ? 8 : 17),
                        _complete ? _nextButton() : _levelDots(),
                        const SizedBox(height: 12),
                        _premiumBottomBar(),
                      ],
                    ),
                  ),
                ),
              );
            }),
          ),
        ],
      ),
    );
  }

  Widget _premiumTopBar(bool narrow) => Row(children: [
        _goldRoundButton(Icons.volume_up_rounded, () {
          // Sistem sesi: ayrı ses/müzik paketine bağımlılık olmadan çalışır.
          SystemSound.play(SystemSoundType.click);
          setState(() => _notice = 'Ses efekti çalındı');
        }, radius: narrow ? 21 : 24),
        const SizedBox(width: 8),
        _goldRoundButton(Icons.menu_rounded, _showMap,
            radius: narrow ? 21 : 24),
        const Spacer(),
        Container(
          padding: const EdgeInsets.fromLTRB(12, 8, 14, 8),
          decoration: BoxDecoration(
            color: _navy.withOpacity(.91),
            borderRadius: BorderRadius.circular(25),
            border: Border.all(color: _gold, width: 1.8),
            boxShadow: const [BoxShadow(color: Color(0x88000000),
                blurRadius: 9, offset: Offset(0, 3))],
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            const Icon(Icons.monetization_on_rounded, color: _gold, size: 24),
            const SizedBox(width: 7),
            Text('$_coins', style: const TextStyle(color: Colors.white,
                fontWeight: FontWeight.w900, fontSize: 18)),
            const SizedBox(width: 7),
            const Icon(Icons.add_circle, color: Color(0xFF65D578), size: 24),
          ]),
        ),
        const SizedBox(width: 8),
        _goldRoundButton(Icons.lightbulb_rounded, _hint,
            radius: narrow ? 21 : 24),
      ]);

  Widget _cityPlaque() => Center(
        child: Container(
          padding: const EdgeInsets.fromLTRB(23, 10, 23, 10),
          constraints: const BoxConstraints(maxWidth: 330),
          decoration: BoxDecoration(
            color: _navy.withOpacity(.90),
            borderRadius: BorderRadius.circular(11),
            border: Border.all(color: _gold.withOpacity(.75), width: 1.1),
            boxShadow: const [BoxShadow(color: Color(0x80000000),
                blurRadius: 16, offset: Offset(0, 5))],
          ),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            const Row(mainAxisSize: MainAxisSize.min, children: [
              Icon(Icons.auto_awesome_rounded, size: 14, color: _gold),
              SizedBox(width: 8),
              Text('Ş E H İ R   H İ K Â Y E L E R İ',
                  style: TextStyle(color: _gold, fontSize: 9,
                      fontWeight: FontWeight.w700, letterSpacing: 1)),
              SizedBox(width: 8),
              Icon(Icons.auto_awesome_rounded, size: 14, color: _gold),
            ]),
            const SizedBox(height: 3),
            FittedBox(
              fit: BoxFit.scaleDown,
              child: Text(_puzzle.city.toUpperCase(),
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: _cream,
                    fontFamily: 'serif',
                    fontSize: 31,
                    fontWeight: FontWeight.w900,
                    shadows: [Shadow(color: Colors.black54,
                        blurRadius: 6, offset: Offset(0, 2))],
                    letterSpacing: 2.0,
                  )),
            ),
            Container(width: 110, height: 1,
                margin: const EdgeInsets.symmetric(vertical: 4),
                color: _gold.withOpacity(.8)),
            Text('B Ö L Ü M   ${_level + 1}',
                style: const TextStyle(color: Colors.white,
                    letterSpacing: 1.5, fontSize: 12,
                    fontWeight: FontWeight.w800)),
          ]),
        ),
      );

  Widget _premiumBoard(double maxCellSize) {
    final cells = _puzzle.cells;
    return LayoutBuilder(builder: (context, region) {
      final size = math.min(maxCellSize,
          (region.maxWidth - 4) / _puzzle.cols).toDouble();
      return Column(mainAxisSize: MainAxisSize.min, children: [
        ...List.generate(_puzzle.rows, (row) => Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: List.generate(_puzzle.cols, (col) =>
                _premiumCell(row, col, size, cells['$row:$col'])),
            )),
      ]);
    });
  }

  Widget _premiumCell(int row, int col, double size, String? letter) {
    if (letter == null) return SizedBox(width: size, height: size);
    final revealed = _hintCells.contains('$row:$col') || _isSolvedCell(row, col);
    return Container(
      width: size - 3,
      height: size - 3,
      margin: const EdgeInsets.all(1.5),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: revealed
              ? const [Color(0xFFFFE19C), Color(0xFFE9A744)]
              : const [Color(0xFFFFFEF5), Color(0xFFFFEDD1)],
        ),
        borderRadius: BorderRadius.circular(7),
        border: Border.all(color: const Color(0xFFCBA26E), width: 1.1),
        boxShadow: const [
          BoxShadow(color: Color(0xAF081527), blurRadius: 5,
              offset: Offset(1, 3)),
          BoxShadow(color: Color(0x66FFFFFF), blurRadius: 2,
              offset: Offset(-1, -1)),
        ],
      ),
      child: Center(
        child: Text(revealed ? letter : '',
            style: TextStyle(color: _navy, fontWeight: FontWeight.w900,
                fontSize: size * .52)),
      ),
    );
  }

  Widget _selectionMessage() => Container(
        height: 31,
        alignment: Alignment.center,
        child: AnimatedSwitcher(
          duration: const Duration(milliseconds: 220),
          child: Text(_selection.isEmpty ? _notice : _selection,
              key: ValueKey(_selection.isEmpty ? _notice : _selection),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              textAlign: TextAlign.center,
              style: TextStyle(
                  color: _cream,
                  fontSize: _selection.isNotEmpty ? 21 : 13,
                  shadows: const [Shadow(color: Colors.black,
                      blurRadius: 8, offset: Offset(0, 2))],
                  fontWeight: FontWeight.w800)),
        ),
      );

  Widget _wheelAndActions(double wheelSize, bool narrow) => Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Column(mainAxisSize: MainAxisSize.min, children: [
            _smallAction(Icons.shuffle_rounded, 'KARIŞTIR', _shuffle),
            const SizedBox(height: 22),
            _smallAction(Icons.stars_rounded, 'BONUS', _showBonuses),
          ]),
          _premiumWheel(wheelSize),
          Column(mainAxisSize: MainAxisSize.min, children: [
            _smallAction(Icons.lightbulb_rounded, '25 ALTIN', _hint),
            const SizedBox(height: 22),
            _smallAction(Icons.card_giftcard_rounded, 'ÖDÜL', _showRewards),
          ]),
        ],
      );

  Widget _premiumWheel(double size) => SizedBox(
        height: size,
        width: size,
        child: Stack(children: [
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onPanDown: (details) => _handleDrag(details.localPosition, size),
            onPanUpdate: (details) => _handleDrag(details.localPosition, size),
            onPanEnd: (_) => _submitWord(),
            onPanCancel: () => setState(() => _dragged.clear()),
            onTapUp: (_) => _submitWord(),
            child: CustomPaint(
              size: Size.square(size),
              painter: LetterWheelPainter(_wheelLetters, _dragged),
            ),
          ),
          Center(
            child: Material(
              color: _navy,
              elevation: 5,
              shape: const CircleBorder(side: BorderSide(color: _gold, width: 2.2)),
              child: InkWell(
                customBorder: const CircleBorder(),
                onTap: _shuffle,
                child: SizedBox(
                  width: size * .23,
                  height: size * .23,
                  child: Icon(Icons.shuffle_rounded, size: size * .12,
                      color: _gold),
